    public class IEqualityComparerIntVector : IEqualityComparer<int[]>
    {
        bool IEqualityComparer<int[]>.Equals(int[]? x, int[]? y)
        {
            if (x.Length != y.Length)
            { return false; }
            for (int i = 0; i < x.Length; i++)
            {
                if (x[i] != y[i])
                { return false; }
            }
            return true;
            //return Enumerable.SequenceEqual(x, y);
            
            //bool result = true;
            //Parallel.ForEach(Partitioner.Create(0, x.Length), (range, loopState) =>
            //{
            //    for (int i = range.Item1; i < range.Item2; i++)
            //    {
            //        if (x[i] != y[i])
            //        {
            //            result = false;
            //            loopState.Stop();
            //            return;
            //        }
            //    }
            //});
            //return result;
            
            //return EqualityComparer<object>.Default.Equals(x, y);
        }

        int IEqualityComparer<int[]>.GetHashCode(int[] obj)
        {
            int result = 17;
            for (int i = 0; i < obj.Length; i++)
            {
                unchecked // nie sprawdza arytmetyki, konwersji typu i umożlwia przekroczanie (przepełnienie) domyślnego zakresu (wynik operacji jest obcięty poprzez odrzucenie wszystkich bitów najbardziej znaczących, które nie mieszczą się w typie docelowym np. max + 1 = 0)
                {
                    result = result * 23 + obj[i];
                }
            }
            return result;
            //return EqualityComparer<object>.Default.GetHashCode(obj);
        }
    }
