			// 08. SIEĆ HOPFIELDA (SIEĆ NEURONOWA) I WYŚWIETLANIE WYNIKÓW (CZASÓW POMIAROWYCH) - GŁÓWNE TESTY (POMIARY)
			log = DateTime.Now + " - Starting major measurement tests.";
			logs.AppendLine(log);	Console.WriteLine(log);
			// zainicjowanie zmiennych pomocniczych (do wyświetlania wyników - czasów testów pomiarowych w postaci całkowitej sumy sekund zamiast formatu hh:mm:ss)
			double timeTotalSeconds = 0;
			int lastVectorNumber = 0;	
			vectorNumber = 0;
			// przygotowanie ścieżki pliku do zapisywania wyników
			pathResultTimes = pathResult + processorName.Replace(' ', '_') + "_" + Math.Sqrt(weightMatrix.Length) + ".txt";
			// wstępny zapis dotychczasowych komunikatów z programu
			using (StreamWriter sw = new StreamWriter(pathResultTimes, false, Encoding.UTF8, 65536))
                {	sw.WriteLine(logs.ToString()); }
			// uruchomienie algorytmów
			for(int currentTest = 1; currentTest <= howManyTests; currentTest++)
			{
				logs.Clear();
				log = DateTime.Now + " - Starting " + currentTest + " test.";
				logs.AppendLine(log);	Console.WriteLine(log);
				foreach(int howManyThreads in threads)
				{
					log = DateTime.Now + " - Starting " + howManyThreads + " threaded tests.";
					logs.AppendLine(log);	Console.WriteLine(log);
					
					// sekwencyjnie (jednowątkowo - w kolejności i losowo)
					timeTotalSeconds = 0;
					for (int j = 0; j < howManyIterations; j++)
					{
						GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
						stopwatchTest.Restart();
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn05Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn05, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn10Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn10, Interlocked.Increment(ref vectorNumber)); }
