						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn55Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn55, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn60Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn60, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn65Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn65, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn70Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn70, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn75Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn75, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn80Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn80, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn85Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn85, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn90Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn90, Interlocked.Increment(ref vectorNumber)); }
						vectorNumber = lastVectorNumber; foreach(int[] vector in validSetSapn95Vectors) { HopfieldNetSingleThreadedSequentiallyInOrder(vector, pathResultSapn95, Interlocked.Increment(ref vectorNumber)); }
						stopwatchTest.Stop();
						timeTotalSeconds += stopwatchTest.Elapsed.TotalSeconds;
						lastVectorNumber = vectorNumber;
					}
