        private static void DeleteFiles(string path)
        {
            string[] filePaths = Directory.GetFiles(path, "*.*", SearchOption.AllDirectories);
            foreach (string filePath in filePaths)
            { File.Delete(filePath); }
        }
        private static string[] GetFilesFrom(string searchFolder, bool isRecursive)
        {
            List<string> filesFound = new();
            var searchOption = isRecursive ? SearchOption.AllDirectories : SearchOption.TopDirectoryOnly;
            foreach (string filter in filters)
            { filesFound.AddRange(Directory.GetFiles(searchFolder, string.Format("*.{0}", filter), searchOption).AsParallel().AsOrdered()); }
            return filesFound.ToArray();
        }
        private static Bitmap[] ConvertFilesToBitmaps(string[] files)
        {
            List<Bitmap> bitmaps = new();
            foreach (string file in files)
            {
                Bitmap bitmap = new(file);
                bitmap.RotateFlip(RotateFlipType.Rotate90FlipX);
                bitmaps.Add(bitmap);
            }
            // Parallel.For(0, files.Length, i => bitmaps.Add(new Bitmap(files[i])));
            return bitmaps.ToArray();
        }
        private static int[][] ConvertBitmapsToIntVectors(Bitmap[] bitmaps)
        {
            List<int[]> vectors = new();
            foreach (Bitmap bitmap in bitmaps)
            {
                int[] vector = new int[bitmap.Height * bitmap.Width];
                int index = 0;
                for (int i = 0; i < bitmap.Height; i++)
                {
                    for (int j = 0; j < bitmap.Width; j++)
                    {
                        if (bitmap.GetPixel(i, j).R < 127 && bitmap.GetPixel(i, j).G < 127 && bitmap.GetPixel(i, j).B < 127)
                        { vector[index++] = 1; } // black
                        else
                        { vector[index++] = -1; } // white
                    }
                }
                vectors.Add(vector);
            }
            return vectors.ToArray();
        }
        private static Bitmap ConvertIntVectorToBitmap(int[] vector)
        {
            int length = (int)Math.Sqrt(vector.Length);
            Bitmap bitmap = new(length, length, PixelFormat.Format32bppArgb);
            //Bitmap bitmap = new(length, length, PixelFormat.Format16bppGrayScale);
            int index = 0;
            for (int i = 0; i < length; i++)
            {
                for (int j = 0; j < length; j++)
                {
                    if (vector[index] == 1)
                    { bitmap.SetPixel(i, j, Color.Black); }
                    else
                    { bitmap.SetPixel(i, j, Color.White); }
                    index++;
                }
            }
            bitmap.RotateFlip(RotateFlipType.Rotate90FlipX);
            return bitmap;
        }
        
        private static void LoadTrainingSet()
        {
            trainSetVectors = new(new IEqualityComparerIntVector());
            string[] filesTrain = GetFilesFrom(searchFolder, true);
            foreach (string file in filesTrain)
            {
                Bitmap bitmap = new(file);
                bitmap.RotateFlip(RotateFlipType.Rotate90FlipX);
                int[] vector = new int[bitmap.Height * bitmap.Width];
                int index = 0;
                for (int i = 0; i < bitmap.Height; i++)
                {
                    for (int j = 0; j < bitmap.Width; j++)
                    {
                        if (bitmap.GetPixel(i, j).R < 127 && bitmap.GetPixel(i, j).G < 127 && bitmap.GetPixel(i, j).B < 127)
                        { vector[index++] = 1; } // black
                        else
                        { vector[index++] = -1; } // white
                    }
                }
                trainSetVectors.Add(vector, file);
            }
        }
        
        private static List<int> GenerateRandomNumbers(int counter, int min, int max)
        {
            if (max <= min || counter < 0 || (counter > max - min && max - min > 0))
            {
                throw new ArgumentOutOfRangeException("Range " + min + " to " + max + " (" + ((Int64)max - (Int64)min) + " values), or counter " + counter + " is illegal.");
            }
            HashSet<int> candidates = new();
            for (int top = max - counter; top < max; top++)
            {
                if (!candidates.Add(random.Next(min, top + 1)))
                { candidates.Add(top); }
            }
            List<int> result = candidates.ToList();
            for (int i = result.Count - 1; i > 0; i--)
            {
                int rand = random.Next(i + 1);
                (result[i], result[rand]) = (result[rand], result[i]);
            }
            return result;
        }
        private static int[] FilterSaltAndPepperNoise(int[] vector, float percent)
        {
            if (percent < 0 || percent > 100)
            { throw new ArgumentOutOfRangeException("The \"percent\" value should be between 0 and 100."); }

            float howManyPixels = percent * vector.Length / 100;
            int[] result = CopyVector(vector);
            int counter = 0;
            while (counter < howManyPixels)
            {
                int index = random.Next(vector.Length);
                if (result[index] == vector[index])
                {
                    if (result[index] == -1 || result[index] == 0)
                    { result[index] = 1; }
                    else
                    { result[index] = -1; }
                    counter++;
                }
            }
            return result;
        }
        
        private static void GenerateImageSapnDataSet(int[] vector, float percent, string pathFrom, string pathTo)
        {
            int[] image = FilterSaltAndPepperNoise(vector, percent);
            Bitmap bitmap = ConvertIntVectorToBitmap(image);
            string[] filePath = pathFrom.Split('\\');
            string fileName = filePath[filePath.Length - 1];
            try
            {
                bitmap.Save(pathTo + fileName, ImageFormat.Bmp);
            }
            catch (Exception)
            {
                Thread.Sleep(100);
                bitmap.Save(pathTo + fileName, ImageFormat.Bmp);
            }
        }
        private static void GenerateValidationDataSets(float percent = 100)
        {
            if (percent < 0)
            { throw new ArgumentOutOfRangeException("The \"percent\" value should be greater than 0."); }
            int[][] vectors = trainSetVectors.Keys.ToArray();
            string[] files = trainSetVectors.Values.ToArray();
            List<int> randomNumbers = new();
            if (percent <= 100)
            {
                randomNumbers = GenerateRandomNumbers((int)Math.Round(percent / 100 * trainSetVectors.Count), 0, trainSetVectors.Count);
            } else
            {
                int length = (int)Math.Round(percent / 100 * trainSetVectors.Count);
                for (int i = 0; i < length; i++)
                {
                    randomNumbers.Add(random.Next(trainSetVectors.Count));
                }
            }
            if (randomNumbers.Count > 1)
            {
                Parallel.ForEach(Partitioner.Create(0, randomNumbers.Count), range => {
                    for (int i = range.Item1; i < range.Item2; i++)
                    {
                        int number = randomNumbers[i];
                        Bitmap bitmap = ConvertIntVectorToBitmap(vectors[number]);
                        string[] filePath = files[number].Split('\\');
                        string fileName = filePath[filePath.Length - 1];
                        try
                        {
                            bitmap.Save(pathValidValid + fileName, ImageFormat.Bmp);
                        }
                        catch (Exception)
                        {
                            Thread.Sleep(50);
                            bitmap.Save(pathValidValid + fileName, ImageFormat.Bmp);
                        }
                        Parallel.Invoke(
                            () => GenerateImageSapnDataSet(vectors[number], 5, files[number], pathSapn05),
                            () => GenerateImageSapnDataSet(vectors[number], 10, files[number], pathSapn10),
                            () => GenerateImageSapnDataSet(vectors[number], 15, files[number], pathSapn15),
                            () => GenerateImageSapnDataSet(vectors[number], 20, files[number], pathSapn20),
                            () => GenerateImageSapnDataSet(vectors[number], 25, files[number], pathSapn25),
                            () => GenerateImageSapnDataSet(vectors[number], 30, files[number], pathSapn30),
                            () => GenerateImageSapnDataSet(vectors[number], 35, files[number], pathSapn35),
                            () => GenerateImageSapnDataSet(vectors[number], 40, files[number], pathSapn40),
                            () => GenerateImageSapnDataSet(vectors[number], 45, files[number], pathSapn45),
                            () => GenerateImageSapnDataSet(vectors[number], 55, files[number], pathSapn55),
                            () => GenerateImageSapnDataSet(vectors[number], 60, files[number], pathSapn60),
                            () => GenerateImageSapnDataSet(vectors[number], 65, files[number], pathSapn65),
                            () => GenerateImageSapnDataSet(vectors[number], 70, files[number], pathSapn70),
                            () => GenerateImageSapnDataSet(vectors[number], 75, files[number], pathSapn75),
                            () => GenerateImageSapnDataSet(vectors[number], 80, files[number], pathSapn80),
                            () => GenerateImageSapnDataSet(vectors[number], 85, files[number], pathSapn85),
                            () => GenerateImageSapnDataSet(vectors[number], 90, files[number], pathSapn90),
                            () => GenerateImageSapnDataSet(vectors[number], 95, files[number], pathSapn95));
                    }
                });
            }
            else if (randomNumbers.Count == 1)
            {
                int number = randomNumbers[0];
                Bitmap bitmap = ConvertIntVectorToBitmap(vectors[number]);
                string[] filePath = files[number].Split('\\');
                string fileName = filePath[filePath.Length - 1];
                try
                {
                    bitmap.Save(pathValidValid + fileName, ImageFormat.Bmp);
                }
                catch (Exception)
                {
                    Thread.Sleep(50);
                    bitmap.Save(pathValidValid + fileName, ImageFormat.Bmp);
                }
                Parallel.Invoke(
                            () => GenerateImageSapnDataSet(vectors[number], 5, files[number], pathSapn05),
                            () => GenerateImageSapnDataSet(vectors[number], 10, files[number], pathSapn10),
                            () => GenerateImageSapnDataSet(vectors[number], 15, files[number], pathSapn15),
                            () => GenerateImageSapnDataSet(vectors[number], 20, files[number], pathSapn20),
                            () => GenerateImageSapnDataSet(vectors[number], 25, files[number], pathSapn25),
                            () => GenerateImageSapnDataSet(vectors[number], 30, files[number], pathSapn30),
                            () => GenerateImageSapnDataSet(vectors[number], 35, files[number], pathSapn35),
                            () => GenerateImageSapnDataSet(vectors[number], 40, files[number], pathSapn40),
                            () => GenerateImageSapnDataSet(vectors[number], 45, files[number], pathSapn45),
                            () => GenerateImageSapnDataSet(vectors[number], 55, files[number], pathSapn55),
                            () => GenerateImageSapnDataSet(vectors[number], 60, files[number], pathSapn60),
                            () => GenerateImageSapnDataSet(vectors[number], 65, files[number], pathSapn65),
                            () => GenerateImageSapnDataSet(vectors[number], 70, files[number], pathSapn70),
                            () => GenerateImageSapnDataSet(vectors[number], 75, files[number], pathSapn75),
                            () => GenerateImageSapnDataSet(vectors[number], 80, files[number], pathSapn80),
                            () => GenerateImageSapnDataSet(vectors[number], 85, files[number], pathSapn85),
                            () => GenerateImageSapnDataSet(vectors[number], 90, files[number], pathSapn90),
                            () => GenerateImageSapnDataSet(vectors[number], 95, files[number], pathSapn95));
            }
            else { throw new Exception("Training data set is too small to generate data validation set. The validation set is at least 40% of the training set. The training set should contain at least two images."); }
        }
        
