        private static float[][] DetermineHebbWeightMatrixParallel()
        {
            locker = new();
            int[][] vectors = trainSetVectors.Keys.ToArray();
            float[][] hebbWeightMatrix = new float[vectors[0].Length][];
            for (int i = 0; i < hebbWeightMatrix.GetLength(0); i++)
            { hebbWeightMatrix[i] = new float[vectors[0].Length]; }
            Parallel.ForEach(Partitioner.Create(0, vectors[0].Length), range =>
            {
                float sum;
                for (int i = range.Item1; i < range.Item2; i++)
                {
                    for (int j = 0; j < i; j++)
                    {
                        sum = 0;
                        foreach (int[] vector in vectors)
                        {
							sum += vector[i] * vector[j];
						}
                        sum /= vectors[0].Length;
                        lock (locker)
                        {
                            hebbWeightMatrix[i][j] = sum;
                            hebbWeightMatrix[j][i] = sum;
                        }
                    }
                }
            });
            return hebbWeightMatrix;
        }
        
        private static string DisplayTime(Stopwatch stopwatch)
        {
            TimeSpan timeSpan = stopwatch.Elapsed;
            string elapsedTime = String.Format("{0:00}:{1:00}:{2:00}:{3:00}.{4:00}", timeSpan.Days, timeSpan.Hours, timeSpan.Minutes, timeSpan.Seconds, timeSpan.Milliseconds / 10);
            return elapsedTime;
        }
        private static float CompareVectors(int[] first, int[] second)
        {
            if (ReferenceEquals(first, second))
            { return 100f; }
            if (first == null || second == null || first.Length != second.Length)
            { return 0f; }

            int result = 0;
            for (int i = 0; i < first.Length; i++)
            {
                if (first[i] != second[i])
                { result++; }
            }
            return 100f * (first.Length - result) / first.Length;
        }
        
        private static (string, float) CheckResult(int[] vector)
        {
            (string path, float similarity) result;
            string guess = ""; float compare = 50; 
            string minGuess = ""; float min = 100;
            string maxGuess = ""; float max = 0;
            result = (guess, 50);

            foreach (int[] vec in trainSetVectors.Keys)
            {
                compare = CompareVectors(vector, vec);
                if (compare > max)
                {
                    max = compare;
                    trainSetVectors.TryGetValue(vec, out maxGuess);
                }
                if (compare < min)
                {
                    min = compare;
                    trainSetVectors.TryGetValue(vec, out minGuess);
                }
                if (compare == 100 || compare == 0)
                {
                    trainSetVectors.TryGetValue(vec, out guess);
                    result = (guess, compare);
                    return result;
                }
            }
            if (result.similarity != 100 || result.similarity != 0)
            {
                if (max > 100 - min) 
                { result = (maxGuess, max); }
                else
                { result = (minGuess, min); }
            }
            return result;
        }
        
        private static int[] CopyVector(int[] vector)
        {
            int[] copy = new int[vector.Length];
            for (int i = 0; i < vector.Length; i++)
            { copy[i] = vector[i]; }
            return copy;
        }
        private static void SaveVectorsToFiles(List<(int[], string)> vectors, string pathTo, int vectorNumber, string methodName)
        {
            int i = 0;
            if (vectors.Count == 0)
            { return; }
            foreach ((int[] vec, string pathFrom) vector in vectors)
            {
                Bitmap bitmap = ConvertIntVectorToBitmap(vector.vec);
                string[] filePath = vector.pathFrom.Split('\\');
                string[] fileNameDot = filePath[filePath.Length - 1].Split('.');
                string fileName = "";
				float progress = vectors.Count - 1;
                DateTime now = DateTime.Now;
                for (int j = 0; j < fileNameDot.Length - 1; j++)
                { fileName += fileNameDot[j]; }
                try
                {
					if (progress != 0)
						bitmap.Save(pathTo + vectorNumber + "_" + Math.Round(100f * i / progress) + "_" + fileName + "_" + methodName + "_" + now.Year + now.Month + now.Day + now.Hour + now.Minute + now.Second + ".bmp", ImageFormat.Bmp);
					else
						bitmap.Save(pathTo + vectorNumber + "_100_" + fileName + "_" + methodName + "_" + now.Year + now.Month + now.Day + now.Hour + now.Minute + now.Second + ".bmp", ImageFormat.Bmp);
                }
                catch (Exception)
                {
                    Thread.Sleep(150);
                    now = DateTime.Now;
                    if (progress != 0)
						bitmap.Save(pathTo + vectorNumber + "_" + Math.Round(100f * i / progress) + "_" + fileName + "_" + methodName + "_" + now.Year + now.Month + now.Day + now.Hour + now.Minute + now.Second + ".bmp", ImageFormat.Bmp);
					else
						bitmap.Save(pathTo + vectorNumber + "_100_" + fileName + "_" + methodName + "_" + now.Year + now.Month + now.Day + now.Hour + now.Minute + now.Second + ".bmp", ImageFormat.Bmp);
                }
                i++;
            }
        }

        // sequentially
		private static void HopfieldNetSingleThreadedSequentiallyInOrder(int[] imageVector, string path, int vectorNumber, bool save = true, int steps = 1, int howManyRepeats = 3, float accuracy = 100)
        {
            if (steps < 1)
                throw new ArgumentOutOfRangeException("The \"steps\" value should be greater than 0.");
            if (howManyRepeats < 1)
                throw new ArgumentOutOfRangeException("The \"howManyRepeats\" value should be greater than 0.");
            if (accuracy < 0 || accuracy > 100)
                throw new ArgumentOutOfRangeException("The \"accuracy\" value should be between 0 and 100.");

            Thread.CurrentThread.Priority = ThreadPriority.Highest;

            int[] vector = CopyVector(imageVector);
            List<(int[], string)> images = new();
            // sprawdzenie czy dane wejściowe nie znajdują się w zbiorze walidacyjnym (brak zmian)
            (string path, float similarity) result = CheckResult(vector);
            images.Add((CopyVector(vector), result.path));
            if (result.similarity == accuracy || result.similarity == (100f - accuracy))
            {
                if (save)
                { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
                return;
            }
            // sieć Hopfielda
            int counter = 1;
            int repeat = howManyRepeats;
            int threshold = vector.Length / steps;

            do
            {
                int unchanged = 1;
                int progress = 1;
				List<(int[], string)> lastIter = new();
                for (int i = 0; i < vector.Length; i++)
                {
                    int index = i;
                    float sum = vector[index];
                    for (int j = 0; j < vector.Length; j++)
                    {
                        sum += weightMatrix[index][j] * vector[j];
                    }
                    sum = Math.Sign(sum);
                    if (sum != vector[index])
                    {
                        if (sum != 0)
                        {
                            vector[index] = (int)sum;
                            unchanged = 0;
                        }
                    }
                    progress++;
                    if (progress % threshold == 0)
                    {
                        // znajdowanie wyniku tzn. uzyskanego obrazu i jak bardzo jest podobny do oryginału
                        result = CheckResult(vector);   // czy znalazł, adres (ścieżka) pliku (nazwa), podobieństwo
                        lastIter.Add((CopyVector(vector), result.path));  // dodawanie obrazu do tymczasowej listy plików do zapisania
                    }
                }

                // jeżeli nie chcemy zapisywać postępów częściej niż jeden raz na iterację, to można ograniczyć się do sprawdzania wyniku już po wykonaniu pętli; w takim wypadku można też usunąć fragmenty kodu związane ze zmienną progress; wtedy można też użyć równoległej wersji funkcji sprawdzającej zbiór uczący i  wyszukującej wyniku (lub lepiej skorzystać z równoległego iequalitycomparera);
                // znajdowanie wyniku tzn. uzyskanego obrazu i jak bardzo jest podobny do oryginału
                //result = CheckResult(vector);   // czy znalazł, adres (ścieżka) pliku (nazwa), podobieństwo
                //images.Add((CopyVector(vector), result.path));  // dodawanie obraz do listy plików do zapisania

                // sprawdzenie 1. warunku (mechanizmu) stopu - czy został znaleziony wynik z podaną dokładnością
                if (result.similarity == accuracy || result.similarity == (100f - accuracy))
                {
                    images.AddRange(lastIter);   // dodawanie obrazów z jednej generacji do listy plików do zapisania
                    break;
                }

                // sprawdzenie 2. warunku (mechanizmu) stopu - czy jakieś piksele zostały zmienione w aktualnej iteracji (czy były jakieś zmiany)
                if (unchanged == 1)
                {
					// opcjonalnie możemy zmniejszać zadaną dokładność wyniku
					/*
					if (accuracy < 50)
                    { accuracy = 100f - accuracy; }
                    accuracy -= repeat;
					*/
                    // przy braku zmian w obrazie, zmniejszamy wartość powtórzeń; jeżeli po wykryciu braku zmian i w trzech kolejnych iteracjach dalej ich nie ma, to zakładamy, że dokładniejszy wynik nie zostanie już uzyskany (znaleziony) oraz kończymy / przerywamy działanie sieci
                    if (repeat != 0)
                    { repeat--; }
                    else
                    { break; }
                }
                else
                {
                    // jeżeli piksele zostały zmienione to resetujemy licznik powtórzeń
                    repeat = howManyRepeats;
                    images.AddRange(lastIter);   // dodawanie obrazów z jednej generacji do listy plików do zapisania
                }
                counter++;
            } while (counter < int.MaxValue);
			// opcjonalnie, jeżeli w oógle nie znalazło wyniku
            /*
            if (result.similarity == accuracy || result.similarity == (100f - accuracy))
            {
                Console.WriteLine("Result was found in " + counter + " iteration.");
                if (result.similarity > 50)
                { Console.WriteLine("Result is image: " + result.path + " with probability " + result.similarity); }
                else
                { Console.WriteLine("Result is negative image: " + result.path + " with probability " + (100 - result.similarity)); }

            }
            else { Console.WriteLine("No result was found."); }
            */
            if (save)
            { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
        }
		
