		// thread
        private static void HopfieldNetMultiThreadedUnsafe(int[] imageVector, string path, int vectorNumber, int howManyThreads, bool save = true, int steps = 1, int howManyRepeats = 3, float accuracy = 100)
        {
            if (steps < 1)
                throw new ArgumentOutOfRangeException("The \"steps\" value should be greater than 0.");
            if (howManyRepeats < 1)
                throw new ArgumentOutOfRangeException("The \"howManyRepeats\" value should be greater than 0.");
            if (accuracy < 0 || accuracy > 100)
                throw new ArgumentOutOfRangeException("The \"accuracy\" value should be between 0 and 100.");
            if (howManyThreads < 1 || howManyThreads > imageVector.Length)
                throw new ArgumentOutOfRangeException("The \"howManyThreads\" value should be between 1 and " + imageVector.Length + " (number of pixels in the image).");

            int[] vector = CopyVector(imageVector);
            List<(int[], string)> images = new();
            (string path, float similarity) result = CheckResult(vector);
            images.Add((CopyVector(vector), result.path));
            if (result.similarity == accuracy || result.similarity == (100f - accuracy))
            {
                if (save)
                { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
                return;
            }

            Thread[] threads = new Thread[howManyThreads];
            int size = vector.Length / howManyThreads;
            int counter = 1;
            int repeat = howManyRepeats;
            int threshold = vector.Length / steps;
            
            do
            {
                int progress = 1;
				int unchanged = 1;
				List<(int[], string)> lastIter = new();
                for (int i = 0; i < howManyThreads; i++)
                {
                    int ind = i;
                    int start = size * ind;
                    int end = size * (ind + 1);
                    threads[ind] = new(() =>
                    {
                        for (int j = start; j < end; j++)
                        {
                            int index = j;
                            float sum = vector[index];
                            for (int k = 0; k < vector.Length; k++)
                            {
                                sum += weightMatrix[index][k] * vector[k];
                            }
                            sum = Math.Sign(sum);
                            if (sum != vector[index])
                            {
                                if (sum != 0)
                                {
                                    vector[index] = (int)sum;
                                    unchanged = 0;
                                }
                            }
                            Interlocked.Increment(ref progress);
                            if (progress % threshold == 0)
                            {
                                result = CheckResult(vector);
                                lastIter.Add((CopyVector(vector), result.path));
                            }
                        }
                    });
					threads[ind].IsBackground = true;
                    threads[ind].Priority = ThreadPriority.Highest;
                    threads[ind].Start();
                }
                foreach (Thread thread in threads)
                    thread.Join();
                
                if (result.similarity == accuracy || result.similarity == (100f - accuracy))
                {
                    images.AddRange(lastIter);
                    break;
                }
                
                if (unchanged == 1)
                {
                    if (repeat != 0)
                    { repeat--; }
                    else
                    { break; }
                }
                else
                {
                    repeat = howManyRepeats;
                    images.AddRange(lastIter);
                }
                counter++;
            } while (counter < int.MaxValue);
            if (save)
            { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
        }
        
        private static void HopfieldNetMultiThreadedThreadMemoryBarrier(int[] imageVector, string path, int vectorNumber, int howManyThreads, bool save = true, int steps = 1, int howManyRepeats = 3, float accuracy = 100)
        {
            if (steps < 1)
                throw new ArgumentOutOfRangeException("The \"steps\" value should be greater than 0.");
            if (howManyRepeats < 1)
                throw new ArgumentOutOfRangeException("The \"howManyRepeats\" value should be greater than 0.");
            if (accuracy < 0 || accuracy > 100)
                throw new ArgumentOutOfRangeException("The \"accuracy\" value should be between 0 and 100.");
            if (howManyThreads < 1 || howManyThreads > imageVector.Length)
                throw new ArgumentOutOfRangeException("The \"howManyThreads\" value should be between 1 and " + imageVector.Length + " (number of pixels in the image).");

            int[] vector = CopyVector(imageVector);
            List<(int[], string)> images = new();
            (string path, float similarity) result = CheckResult(vector);
            images.Add((CopyVector(vector), result.path));
            if (result.similarity == accuracy || result.similarity == (100f - accuracy))
            {
                if (save)
                { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
                return;
            }

            Thread[] threads = new Thread[howManyThreads];
            int size = vector.Length / howManyThreads;
            int counter = 1;
            int repeat = howManyRepeats;
            int threshold = vector.Length / steps;
            
            do
            {
                int progress = 1;
				int unchanged = 1;
				List<(int[], string)> lastIter = new();
                for (int i = 0; i < howManyThreads; i++)
                {
                    int ind = i;
                    int start = size * ind;
                    int end = size * (ind + 1);
                    threads[ind] = new(() =>
                    {
                        for (int j = start; j < end; j++)
                        {
                            int index = j;
                            float sum = vector[index];
                            for (int k = 0; k < vector.Length; k++)
                            {
                                sum += weightMatrix[index][k] * vector[k];
                            }
                            sum = Math.Sign(sum);
                            if (sum != vector[index])
                            {
                                if (sum != 0)
                                {
                                    Thread.MemoryBarrier();
                                    vector[index] = (int)sum;
                                    Thread.MemoryBarrier();
                                    unchanged = 0;
                                    Thread.MemoryBarrier();
                                }
                            }
                            Interlocked.Increment(ref progress);
                            if (progress % threshold == 0)
                            {
                                result = CheckResult(vector);
                                lastIter.Add((CopyVector(vector), result.path));
                            }
                        }
                    });
					threads[ind].IsBackground = true;
                    threads[ind].Priority = ThreadPriority.Highest;
                    threads[ind].Start();
                }
                foreach (Thread thread in threads)
                    thread.Join();

                if (result.similarity == accuracy || result.similarity == (100f - accuracy))
                {
                    images.AddRange(lastIter);
                    break;
                }

                if (unchanged == 1)
                {
                    if (repeat != 0)
                    { repeat--; }
                    else
                    { break; }
                }
                else
                {
                    repeat = howManyRepeats;
                    images.AddRange(lastIter);
                }
                counter++;
            } while (counter < int.MaxValue);
            if (save)
            { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
        }
        
