                for (int i = 0; i < howManyThreads; i++)
                {
                    int ind = i;
                    int start = size * ind;
                    int end = size * (ind + 1);
                    ThreadPool.QueueUserWorkItem(state =>
                    {
                        try
                        {
                            for (int j = start; j < end; j++)
                            {
                                int index = j;
                                float sum = vector[index];
                                for (int k = 0; k < vector.Length; k++)
