                }

                if (unchanged == 1)
                {
                    if (repeat != 0)
                    { repeat--; }
                    else
                    { break; }
                }
                else
                {
                    repeat = howManyRepeats;
                    images.AddRange(lastIter);
                }
                counter++;
            } while (counter < int.MaxValue);
            if (save)
            { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
			ThreadPool.SetMinThreads(minThreadsInThreadPool,minThreadsInThreadPool);
			ThreadPool.SetMaxThreads(maxThreadsInThreadPool,maxThreadsInThreadPool);
        }
        
