			ManualResetEventSlim manualResetEventSlim = new(false);
			ThreadPool.SetMinThreads(howManyThreads, howManyThreads);
            ThreadPool.SetMaxThreads(howManyThreads, howManyThreads);
			int numberOfThreads = howManyThreads;
            int size = vector.Length / howManyThreads;
