		private static void HopfieldNetThreadPoolBarrierAutoResetEvent(int[] imageVector, string path, int vectorNumber, int howManyThreads, bool save = true, int steps = 1, int howManyRepeats = 3, float accuracy = 100)
        {
            if (steps < 1)
                throw new ArgumentOutOfRangeException("The \"steps\" value should be greater than 0.");
            if (howManyRepeats < 1)
                throw new ArgumentOutOfRangeException("The \"howManyRepeats\" value should be greater than 0.");
            if (accuracy < 0 || accuracy > 100)
                throw new ArgumentOutOfRangeException("The \"accuracy\" value should be between 0 and 100.");
            if (howManyThreads < 1 || howManyThreads > imageVector.Length)
                throw new ArgumentOutOfRangeException("The \"howManyThreads\" value should be between 1 and " + imageVector.Length + " (number of pixels in the image).");

            int[] vector = CopyVector(imageVector);
            List<(int[], string)> images = new();
            (string path, float similarity) result = CheckResult(vector);
            images.Add((CopyVector(vector), result.path));
            if (result.similarity == accuracy || result.similarity == (100f - accuracy))
            {
                if (save)
                { SaveVectorsToFiles(images, path, vectorNumber, MethodBase.GetCurrentMethod().Name); }
                return;
            }

            autoResetEvent = new(true);
            barrier = new(howManyThreads + 1);
            ThreadPool.SetMinThreads(howManyThreads, howManyThreads);
            ThreadPool.SetMaxThreads(howManyThreads, howManyThreads);
            int size = vector.Length / howManyThreads;
            int counter = 1;
            int repeat = howManyRepeats;
            int threshold = vector.Length / steps;
            
            do
            {
                int progress = 1;
				int unchanged = 1;
