                                if (sum != vector[index])
                                {
                                    if (sum != 0)
                                    {
                                        autoResetEvent.WaitOne();
                                        vector[index] = (int)sum;
                                        unchanged = 0;
                                        autoResetEvent.Set();
                                    }
                                }
                                Interlocked.Increment(ref progress);
                                if (progress % threshold == 0)
                                {
                                    result = CheckResult(vector);
                                    lastIter.Add((CopyVector(vector), result.path));
                                }
                            }
