                }
                barrier.SignalAndWait();

                if (result.similarity == accuracy || result.similarity == (100f - accuracy))
                {
                    images.AddRange(lastIter);
                    break;
                }

                if (unchanged == 1)
                {
                    if (repeat != 0)
                    { repeat--; }
                    else
                    { break; }
                }
                else
                {
                    repeat = howManyRepeats;
                    images.AddRange(lastIter);
                }
                counter++;
            } while (counter < int.MaxValue);
            if (save)
